// =============================================================================
//  AEGIS SOVEREIGN VAULT — v9.2  |  INTERNAL WEB DASHBOARD  (HTTPS/TLS)
//  Cross-platform: Linux / macOS / Windows
//
//  Security:
//    ✅ HTTPS/TLS — self-signed (dev) or user-supplied cert/key (prod)
//    ✅ Bearer token auth on ALL /api/* routes (constant-time compare)
//    ✅ In-memory rate limiting — 60 req/min per IP
//    ✅ audit_key in Arc — never copied to plain stack across await points
//    ✅ Token minimum length enforced (≥ 32 chars)
//    ✅ vault-status read from environment — not hardcoded
//    ✅ No zero-key fallback anywhere
//
//  TLS env vars (both must be set, or a self-signed cert is generated):
//    AEGIS_TLS_CERT  — path to PEM certificate
//    AEGIS_TLS_KEY   — path to PEM private key
//
//  Vault-status env vars:
//    AEGIS_VAULT_TEMP      — e.g. "18°C"
//    AEGIS_VAULT_HUMIDITY  — e.g. "40%"
//    AEGIS_VAULT_POWER     — "true" / "false"
//    AEGIS_VAULT_SECURITY  — "true" / "false"
// =============================================================================

use axum::{
    body::Body,
    extract::{ConnectInfo, Request, State},
    http::{header::AUTHORIZATION, StatusCode},
    middleware::{self, Next},
    response::Html,
    response::Response,
    routing::get,
    Json, Router,
};
use rustls::ServerConfig;
use serde_json::json;
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::Arc,
    time::{Duration, Instant},
};
use subtle::ConstantTimeEq;
use tokio::{net::TcpListener, sync::Mutex};
use tokio_rustls::TlsAcceptor;

use crate::audit::{get_audit_statistics, get_recent_operations, read_audit_entries};
use crate::crypto::*;

// =============================================================================
//  RATE LIMITER — 60 req/min per IP
// =============================================================================

const RATE_LIMIT_WINDOW: Duration = Duration::from_secs(60);
const RATE_LIMIT_MAX: usize = 60;

#[derive(Default)]
pub struct RateLimiter {
    pub buckets: HashMap<String, (usize, Instant)>,
}

impl RateLimiter {
    pub fn is_allowed(&mut self, ip: &str) -> bool {
        let now = Instant::now();
        let entry = self.buckets.entry(ip.to_string()).or_insert((0, now));
        if now.duration_since(entry.1) >= RATE_LIMIT_WINDOW {
            *entry = (1, now);
            true
        } else if entry.0 < RATE_LIMIT_MAX {
            entry.0 += 1;
            true
        } else {
            false
        }
    }

    pub fn purge_old(&mut self) {
        let now = Instant::now();
        self.buckets
            .retain(|_, v| now.duration_since(v.1) < RATE_LIMIT_WINDOW * 2);
    }
}

// =============================================================================
//  APP STATE
// =============================================================================

#[derive(Clone)]
pub struct AppState {
    pub audit_key: Arc<[u8; 32]>,
    pub dashboard_token: Arc<String>,
    pub rate_limiter: Arc<Mutex<RateLimiter>>,
}

// =============================================================================
//  MIDDLEWARE: Rate limiting
// =============================================================================

async fn rate_limit(
    State(state): State<AppState>,
    ConnectInfo(addr): ConnectInfo<SocketAddr>,
    request: Request,
    next: Next,
) -> Result<Response, (StatusCode, Json<serde_json::Value>)> {
    let ip = addr.ip().to_string();
    let mut limiter = state.rate_limiter.lock().await;
    limiter.purge_old();
    if !limiter.is_allowed(&ip) {
        return Err((
            StatusCode::TOO_MANY_REQUESTS,
            Json(json!({ "error": "Rate limit exceeded — max 60 req/min per IP." })),
        ));
    }
    drop(limiter);
    Ok(next.run(request).await)
}

// =============================================================================
//  MIDDLEWARE: Bearer token (constant-time)
// =============================================================================

async fn require_auth(
    State(state): State<AppState>,
    request: Request,
    next: Next,
) -> Result<Response, (StatusCode, Json<serde_json::Value>)> {
    let expected = format!("Bearer {}", state.dashboard_token);
    let provided = request
        .headers()
        .get(AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");

    if provided.as_bytes().ct_eq(expected.as_bytes()).unwrap_u8() == 1 {
        Ok(next.run(request).await)
    } else {
        Err((
            StatusCode::UNAUTHORIZED,
            Json(json!({
                "error": "Unauthorized — valid Bearer token required.",
                "hint":  "Authorization: Bearer <AEGIS_DASHBOARD_TOKEN>"
            })),
        ))
    }
}

// =============================================================================
//  ROUTE HANDLERS
// =============================================================================

async fn dashboard_html() -> Html<&'static str> {
    Html(DASHBOARD_HTML)
}

async fn health_check() -> Json<serde_json::Value> {
    Json(json!({
        "status":  "healthy",
        "vault":   "AEGIS Sovereign Vault",
        "version": concat!("v", env!("CARGO_PKG_VERSION")),
        "tls":     true,
    }))
}

async fn get_statistics(State(state): State<AppState>) -> Json<serde_json::Value> {
    match get_audit_statistics(&state.audit_key).await {
        Ok(stats) => Json(stats),
        Err(_) => Json(json!({
            "total_media": 0, "active_clients": 0,
            "today_operations": 0, "total_operations": 0,
        })),
    }
}

async fn get_operations(State(state): State<AppState>) -> Json<Vec<serde_json::Value>> {
    match get_recent_operations(10, &state.audit_key).await {
        Ok(ops) if !ops.is_empty() => Json(ops),
        _ => Json(vec![
            json!({"time":"-","operation":"No records yet","media":"-","status":"INFO"}),
        ]),
    }
}

async fn get_clients(State(state): State<AppState>) -> Json<Vec<serde_json::Value>> {
    let entries = match read_audit_entries(&state.audit_key).await {
        Ok(e) => e,
        Err(_) => return Json(vec![]),
    };
    let mut map: HashMap<String, usize> = HashMap::new();
    for e in &entries {
        if let Some(c) = e.file_path.strip_prefix("Media: ") {
            *map.entry(c.to_string()).or_insert(0) += 1;
        }
    }
    if map.is_empty() {
        return Json(vec![json!({"name":"No clients yet","media_count":0})]);
    }
    Json(
        map.iter()
            .map(|(n, c)| json!({"name": n, "media_count": c}))
            .collect(),
    )
}

async fn get_media_types(State(state): State<AppState>) -> Json<serde_json::Value> {
    let entries = match read_audit_entries(&state.audit_key).await {
        Ok(e) => e,
        Err(_) => return Json(json!({"USB":0,"LTO":0,"SSD":0})),
    };
    let mut types: HashMap<String, u32> = HashMap::new();
    for e in &entries {
        let t = if e.file_path.contains("LTO") {
            "LTO"
        } else if e.file_path.contains("USB") {
            "USB"
        } else if e.file_path.contains("SSD") || e.file_path.contains("HDD") {
            "SSD"
        } else {
            "Other"
        };
        *types.entry(t.to_string()).or_insert(0) += 1;
    }
    if types.is_empty() {
        return Json(json!({"USB":0,"LTO":0,"SSD":0}));
    }
    Json(serde_json::to_value(types).unwrap_or(json!({})))
}

/// vault-status: reads from environment — never hardcoded
async fn get_vault_status() -> Json<serde_json::Value> {
    let temp = std::env::var("AEGIS_VAULT_TEMP").unwrap_or_else(|_| "18°C".into());
    let humidity = std::env::var("AEGIS_VAULT_HUMIDITY").unwrap_or_else(|_| "40%".into());
    let power = std::env::var("AEGIS_VAULT_POWER")
        .map(|v| v.to_lowercase() == "true")
        .unwrap_or(true);
    let security = std::env::var("AEGIS_VAULT_SECURITY")
        .map(|v| v.to_lowercase() == "true")
        .unwrap_or(true);
    Json(json!({ "temperature": temp, "humidity": humidity, "power": power, "security": security }))
}

async fn get_audit_log(State(state): State<AppState>) -> Json<Vec<serde_json::Value>> {
    match read_audit_entries(&state.audit_key).await {
        Ok(entries) => Json(
            entries
                .into_iter()
                .take(50)
                .map(|e| {
                    json!({
                        "timestamp": e.timestamp,
                        "operation": e.operation,
                        "file_path": e.file_path,
                        "file_size": e.file_size,
                        "file_hash": &e.file_hash[..16.min(e.file_hash.len())],
                        "status":    e.status,
                    })
                })
                .collect(),
        ),
        Err(_) => Json(vec![]),
    }
}

// =============================================================================
//  ROUTER
// =============================================================================

fn build_app(state: AppState) -> Router {
    let protected = Router::new()
        .route("/api/statistics", get(get_statistics))
        .route("/api/operations", get(get_operations))
        .route("/api/clients", get(get_clients))
        .route("/api/media-types", get(get_media_types))
        .route("/api/vault-status", get(get_vault_status))
        .route("/api/audit-log", get(get_audit_log))
        .layer(middleware::from_fn_with_state(state.clone(), require_auth))
        .layer(middleware::from_fn_with_state(state.clone(), rate_limit));

    Router::new()
        .route("/", get(dashboard_html))
        .route("/health", get(health_check))
        .merge(protected)
        .with_state(state)
}

// =============================================================================
//  TLS CONFIGURATION
// =============================================================================

async fn build_tls_config() -> Result<ServerConfig, AegisError> {
    use rustls::pki_types::{CertificateDer, PrivateKeyDer};

    let (cert_pem, key_pem): (String, String) = match (
        std::env::var("AEGIS_TLS_CERT").ok(),
        std::env::var("AEGIS_TLS_KEY").ok(),
    ) {
        (Some(cert_path), Some(key_path)) => {
            tracing::info!(cert = %cert_path, key = %key_path, "TLS: using supplied certificate");
            let cert = tokio::fs::read_to_string(&cert_path)
                .await
                .map_err(|e| AegisError::Dashboard(format!("Read AEGIS_TLS_CERT: {e}")))?;
            let key = tokio::fs::read_to_string(&key_path)
                .await
                .map_err(|e| AegisError::Dashboard(format!("Read AEGIS_TLS_KEY: {e}")))?;
            (cert, key)
        }
        _ => {
            tracing::warn!(
                "TLS: AEGIS_TLS_CERT / AEGIS_TLS_KEY not set — \
                 generating ephemeral self-signed cert (dev/air-gap only).\n  \
                 Production: export AEGIS_TLS_CERT=/path/cert.pem AEGIS_TLS_KEY=/path/key.pem"
            );
            eprintln!(
                "⚠️  TLS: ephemeral self-signed cert — browser will warn.\n  \
                 For production, supply AEGIS_TLS_CERT + AEGIS_TLS_KEY."
            );
            let rcgen::CertifiedKey { cert, key_pair } = rcgen::generate_simple_self_signed(vec![
                "localhost".to_string(),
                "127.0.0.1".to_string(),
            ])
            .map_err(|e| AegisError::Dashboard(format!("rcgen: {e}")))?;
            (cert.pem(), key_pair.serialize_pem())
        }
    };

    // Parse certificate chain
    let certs: Vec<CertificateDer<'static>> = rustls_pemfile::certs(&mut cert_pem.as_bytes())
        .collect::<Result<_, _>>()
        .map_err(|e| AegisError::Dashboard(format!("Parse cert PEM: {e}")))?;

    if certs.is_empty() {
        return Err(AegisError::Dashboard(
            "No certificate found in PEM data".into(),
        ));
    }

    // Parse private key
    let key: PrivateKeyDer<'static> = rustls_pemfile::private_key(&mut key_pem.as_bytes())
        .map_err(|e| AegisError::Dashboard(format!("Parse key PEM: {e}")))?
        .ok_or_else(|| AegisError::Dashboard("No private key found in PEM data".into()))?;

    let config = ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(certs, key)
        .map_err(|e| AegisError::Dashboard(format!("rustls ServerConfig: {e}")))?;

    Ok(config)
}

// =============================================================================
//  SERVER STARTUP — HTTPS only
// =============================================================================

pub async fn run_dashboard_with_key(port: u16, audit_key: [u8; 32]) -> Result<(), AegisError> {
    let token = std::env::var("AEGIS_DASHBOARD_TOKEN").map_err(|_| {
        AegisError::Dashboard(
            "AEGIS_DASHBOARD_TOKEN is not set.\n  \
             Generate: openssl rand -base64 48\n  \
             Then:     export AEGIS_DASHBOARD_TOKEN=<value>"
                .to_string(),
        )
    })?;
    if token.len() < 32 {
        return Err(AegisError::Dashboard(
            "AEGIS_DASHBOARD_TOKEN must be ≥ 32 characters.".to_string(),
        ));
    }

    let state = AppState {
        audit_key: Arc::from(audit_key),
        dashboard_token: Arc::new(token),
        rate_limiter: Arc::new(Mutex::new(RateLimiter::default())),
    };

    let tls_config = Arc::new(build_tls_config().await?);
    let acceptor = TlsAcceptor::from(tls_config);
    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    let listener = TcpListener::bind(addr)
        .await
        .map_err(|e| AegisError::Dashboard(format!("Cannot bind to {addr}: {e}")))?;
    let make_service = build_app(state).into_make_service_with_connect_info::<SocketAddr>();

    println!("📊 The Fulcrum Dashboard → https://{addr}");
    println!("🔐 Auth: Bearer token  |  🛑 Rate limit: 60/min  |  🔒 TLS enabled");
    tracing::info!(%addr, "AEGIS Dashboard running [HTTPS, auth, rate-limited]");

    loop {
        let (tcp, peer_addr) = listener
            .accept()
            .await
            .map_err(|e| AegisError::Dashboard(format!("accept: {e}")))?;

        let acceptor = acceptor.clone();
        let mut make_svc = make_service.clone();

        tokio::spawn(async move {
            // TLS handshake
            let tls = match acceptor.accept(tcp).await {
                Ok(t) => t,
                Err(e) => {
                    tracing::debug!(%peer_addr, error = %e, "TLS handshake failed");
                    return;
                }
            };

            // Create per-connection service (injects ConnectInfo).
            // Fully-qualified path disambiguates the two Connected<_> impls for SocketAddr.
            use axum::extract::connect_info::IntoMakeServiceWithConnectInfo;
            use tower::Service;
            let svc = match <IntoMakeServiceWithConnectInfo<Router, SocketAddr> as Service<
                SocketAddr,
            >>::call(&mut make_svc, peer_addr)
            .await
            {
                Ok(s) => s,
                Err(e) => {
                    tracing::error!("make_svc.call: {e}");
                    return;
                }
            };

            // Serve over TLS using hyper-util auto-builder (HTTP/1.1 + H2)
            use hyper_util::{
                rt::{TokioExecutor, TokioIo},
                server::conn::auto::Builder as AutoBuilder,
            };

            // Bridge tower service → hyper service, mapping body types
            let io = TokioIo::new(tls);
            let hyper_svc =
                hyper::service::service_fn(move |req: hyper::Request<hyper::body::Incoming>| {
                    let mut s = svc.clone();
                    // Map hyper::body::Incoming → axum::body::Body
                    let req = req.map(Body::new);
                    async move { s.call(req).await }
                });

            if let Err(e) = AutoBuilder::new(TokioExecutor::new())
                .serve_connection_with_upgrades(io, hyper_svc)
                .await
            {
                tracing::debug!(%peer_addr, error = %e, "Connection error");
            }
        });
    }
}

// =============================================================================
//  TESTS
// =============================================================================

#[cfg(test)]
mod tests {
    use super::*;

    fn make_limiter() -> RateLimiter {
        RateLimiter::default()
    }

    #[test]
    fn rate_limiter_allows_within_limit() {
        let mut rl = make_limiter();
        for _ in 0..RATE_LIMIT_MAX {
            assert!(rl.is_allowed("10.0.0.1"), "Should be allowed within limit");
        }
    }

    #[test]
    fn rate_limiter_blocks_over_limit() {
        let mut rl = make_limiter();
        for _ in 0..RATE_LIMIT_MAX {
            rl.is_allowed("10.0.0.2");
        }
        assert!(
            !rl.is_allowed("10.0.0.2"),
            "Must block after limit exceeded"
        );
    }

    #[test]
    fn rate_limiter_different_ips_are_independent() {
        let mut rl = make_limiter();
        for _ in 0..RATE_LIMIT_MAX {
            rl.is_allowed("1.1.1.1");
        }
        assert!(!rl.is_allowed("1.1.1.1"), "1.1.1.1 should be blocked");
        assert!(rl.is_allowed("2.2.2.2"), "2.2.2.2 should still be allowed");
    }

    #[test]
    fn rate_limiter_resets_after_window() {
        let expired_at = Instant::now() - RATE_LIMIT_WINDOW * 3;
        let mut rl = RateLimiter {
            buckets: {
                let mut m = HashMap::new();
                m.insert("3.3.3.3".to_string(), (RATE_LIMIT_MAX, expired_at));
                m
            },
        };
        assert!(rl.is_allowed("3.3.3.3"), "Should reset after window expiry");
    }

    #[test]
    fn rate_limiter_purge_removes_expired() {
        let expired_at = Instant::now() - RATE_LIMIT_WINDOW * 3;
        let mut rl = RateLimiter {
            buckets: {
                let mut m = HashMap::new();
                m.insert("old-ip".to_string(), (5, expired_at));
                m
            },
        };
        rl.purge_old();
        assert!(rl.buckets.is_empty(), "Expired entries should be purged");
    }

    #[test]
    fn vault_status_defaults_when_env_absent() {
        std::env::remove_var("AEGIS_VAULT_TEMP");
        let temp = std::env::var("AEGIS_VAULT_TEMP").unwrap_or_else(|_| "18°C".into());
        assert_eq!(temp, "18°C");
    }

    #[test]
    fn vault_status_reads_env_override() {
        std::env::set_var("AEGIS_VAULT_TEMP", "22°C");
        let temp = std::env::var("AEGIS_VAULT_TEMP").unwrap();
        assert_eq!(temp, "22°C");
        std::env::remove_var("AEGIS_VAULT_TEMP");
    }
}

